-- Hostinger MariaDB 10.6+ / MySQL 8.0.16+ (InnoDB, utf8mb4).
-- Import into the selected database in phpMyAdmin. No database is dropped.
-- UUIDs are generated by the application, not database-specific functions.
CREATE TABLE IF NOT EXISTS admins (
  id CHAR(36) PRIMARY KEY,
  username VARCHAR(100) NOT NULL UNIQUE,
  email VARCHAR(200) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  role ENUM('super_admin','content_editor') NOT NULL DEFAULT 'super_admin',
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_login_at DATETIME(3) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_sessions (
  id CHAR(36) PRIMARY KEY,
  admin_id CHAR(36) NOT NULL,
  token_hash VARCHAR(64) NOT NULL UNIQUE,
  expires_at DATETIME(3) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_seen_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE CASCADE,
  INDEX sessions_admin_expiry_idx (admin_id, expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS login_challenges (
  id CHAR(36) PRIMARY KEY,
  admin_id CHAR(36) NOT NULL,
  code_hash VARCHAR(255) NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  attempts INT NOT NULL DEFAULT 0,
  consumed_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE CASCADE,
  INDEX challenges_expiry_idx (expires_at, consumed_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS site_settings (
  id INT PRIMARY KEY CHECK (id = 1),
  business_name VARCHAR(120) NOT NULL DEFAULT 'Amigos Car Care',
  tagline VARCHAR(180) NOT NULL DEFAULT 'Premium Car Care. Done Right.',
  description VARCHAR(1200) NOT NULL DEFAULT 'Expert car care in Qatar.',
  public_email VARCHAR(200) NOT NULL DEFAULT 'info@amigoscarcare.com',
  public_phone VARCHAR(40) NOT NULL DEFAULT '+974 7778 9303',
  hero_image VARCHAR(300) NOT NULL DEFAULT '/assets/workshop-web.jpg',
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_by CHAR(36) NULL,
  FOREIGN KEY (updated_by) REFERENCES admins(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS app_migrations (
  migration_id VARCHAR(180) PRIMARY KEY,
  applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS services (
  id CHAR(36) PRIMARY KEY,
  slug VARCHAR(100) NOT NULL UNIQUE,
  title_en VARCHAR(160) NOT NULL,
  title_ar VARCHAR(160) NOT NULL DEFAULT '',
  summary_en VARCHAR(600) NOT NULL,
  summary_ar VARCHAR(600) NOT NULL DEFAULT '',
  details_en JSON NOT NULL DEFAULT ('[]'),
  details_ar JSON NOT NULL DEFAULT ('[]'),
  image_path VARCHAR(300) NOT NULL,
  gallery_images JSON NOT NULL DEFAULT ('[]'),
  sort_order INT NOT NULL DEFAULT 0,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  INDEX services_active_order_idx (active, sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS branches (
  id CHAR(36) PRIMARY KEY,
  slug VARCHAR(100) NOT NULL UNIQUE,
  name_en VARCHAR(160) NOT NULL,
  name_ar VARCHAR(160) NOT NULL DEFAULT '',
  address_en VARCHAR(300) NOT NULL,
  address_ar VARCHAR(300) NOT NULL DEFAULT '',
  phone VARCHAR(60) NOT NULL DEFAULT '',
  hours VARCHAR(120) NOT NULL DEFAULT '8:00 AM – 10:00 PM',
  map_url VARCHAR(500) NOT NULL DEFAULT '',
  image_path VARCHAR(300) NOT NULL DEFAULT '/assets/branch-doha-web.jpg',
  sort_order INT NOT NULL DEFAULT 0,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS offers (
  id CHAR(36) PRIMARY KEY,
  title_en VARCHAR(160) NOT NULL,
  title_ar VARCHAR(160) NOT NULL DEFAULT '',
  description_en TEXT NOT NULL,
  description_ar TEXT NOT NULL DEFAULT (''),
  discount VARCHAR(100) NOT NULL DEFAULT '',
  badge VARCHAR(80) NOT NULL DEFAULT '',
  image_path VARCHAR(300) NOT NULL DEFAULT '/assets/workshop-web.jpg',
  branch_slug VARCHAR(100) NOT NULL DEFAULT 'all',
  promo_code VARCHAR(80) NOT NULL DEFAULT '',
  terms_en TEXT NOT NULL DEFAULT (''),
  terms_ar TEXT NOT NULL DEFAULT (''),
  starts_at DATETIME(3) NULL,
  ends_at DATETIME(3) NULL,
  status ENUM('draft','published','paused','archived') NOT NULL DEFAULT 'draft',
  created_by CHAR(36) NULL,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (created_by) REFERENCES admins(id),
  INDEX offers_public_idx (status, starts_at, ends_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS enquiries (
  id CHAR(36) PRIMARY KEY,
  kind ENUM('business','career','booking') NOT NULL,
  contact_name VARCHAR(140) NOT NULL,
  email VARCHAR(200) NOT NULL,
  phone VARCHAR(40) NOT NULL DEFAULT '',
  subject VARCHAR(180) NOT NULL DEFAULT '',
  message TEXT NOT NULL DEFAULT (''),
  metadata JSON NOT NULL DEFAULT ('{}'),
  status ENUM('new','reviewing','contacted','closed','spam') NOT NULL DEFAULT 'new',
  notification_sent BOOLEAN NOT NULL DEFAULT FALSE,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  INDEX enquiries_kind_status_idx (kind, status, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS audit_events (
  id CHAR(36) PRIMARY KEY,
  admin_id CHAR(36) NULL,
  action VARCHAR(100) NOT NULL,
  entity VARCHAR(100) NOT NULL,
  entity_id VARCHAR(100) NOT NULL DEFAULT '',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  FOREIGN KEY (admin_id) REFERENCES admins(id),
  INDEX audit_created_idx (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS analytics_page_views (
  id CHAR(36) PRIMARY KEY,
  page_path VARCHAR(240) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  INDEX analytics_page_time_idx (created_at, page_path)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO site_settings(id) VALUES(1) ON DUPLICATE KEY UPDATE id=id;

CREATE TABLE IF NOT EXISTS uploaded_images (
  id VARCHAR(36) PRIMARY KEY,
  mime_type VARCHAR(40) NOT NULL,
  image_base64 LONGTEXT NOT NULL
);
